insert into rwadar_catalogo.alertas (revision_id,plataforma_id,codigo,detalle) select 'eca89db7-aac5-35fa-f792-5bffbe8795e2'::uuid,id,'terminos_finales_no_confirmados','Que el folleto esté «aprobado por la FMA» no es un aval ni una licencia de Midas: según el folleto base del 17/07/2026, la FMA solo revisa que esté completo, se entienda y sea coherente, y el emisor no queda regulado por ella. Si pueden entrar minoristas del EEE lo deciden las condiciones finales de mTBILL; las del 17/07/2026 no lo prohíben, pero eso no confirma que la web te deje darte de alta.' from public.plataformas where slug='midas' on conflict do nothing;
