insert into rwadar_catalogo.ofertas (revision_id,slug,tipo,titulo,plataforma_slug,plataforma_nombre,categoria_slug,pais,resumen,url,verificada_el,vigencia_dias,permanente,disponible_es,eu,fuera_ladrillo,puntuacion,rentabilidad,precio,metricas,avisos,estado_revision,fuentes_actuales,patrocinada,documentacion,coleccion) values ('eca89db7-aac5-35fa-f792-5bffbe8795e2'::uuid,'switzerlend','valor','Switzerlend','aktionariat','Aktionariat · LENDS','acciones-y-capital-privado','CH','Acciones preferentes C1 tokenizadas de Switzerlend AG, operadora de la plataforma de préstamos LEND. El emisor las vende a precio fijado por él; no las recompra.','https://shares.lend.ch/','2026-11-20'::date,7,false,null,null,true,null,null,null,'[{"etiqueta":"Clase","valor":"Preferente C1 (preferencia en liquidación)"},{"etiqueta":"Supervisor","valor":"Sin supervisión prudencial: no figura en el registro de autorizados de FINMA (20/11/2026); afiliada a PolyReg solo a efectos de blanqueo"}]'::jsonb,'[{"texto":"Referencia editorial gratuita. El proveedor comprueba admisión, condiciones y riesgos; RWAdar no recibe dinero de inversiones.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-20"},{"texto":"Según las condiciones de su portal (§9.1, versión del 30/10/2026), la venta del emisor es solo para residentes en Suiza o el EEE, con un tope total de 100.000 € para el EEE; no se publica cuánto queda.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-20"},{"texto":"Es capital de la empresa, no una inversión en los préstamos de LEND.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-20"},{"texto":"La salida depende de compradores en un secundario en cripto con muy poca demanda.","tono":"warn","esAntiguedad":false,"verificadaEl":"2026-11-20"},{"texto":"Su web dice que el emisor recompra acciones si tiene liquidez, pero el acuerdo firmado no le obliga y el 20/11/2026 la recompra seguía desactivada y casi sin fondos (0,03 ZCHF).","tono":"warn","esAntiguedad":false,"verificad