-- Entrega 2026-11-20 (preparada el 20/11/2026) sobre la revisión publicada 2026-11-13 (434217eb-9b7f-1cd9-a851-fbde7bced2bf). Ciclo pedido y autorizado por el responsable del proyecto.
-- Radar y 22 fichas comprobados hoy; 25 plataformas y 22 ofertas (8/13/1). Solo escribe en rwadar_catalogo.
-- Generado por rwadar-app/data/verificaciones/2026-11-20-v2/preparar-entrega.mjs; revisar antes de aplicar.
-- Generado localmente; revisar antes de cualquier aplicación remota.
-- Este aplicador importa y aprueba al final, únicamente si pasan todas las guardas.
begin isolation level serializable;
do $guarda$
declare actual uuid; retirada boolean;
begin
  select revision_id into actual from rwadar_catalogo.publicacion_v2 where unica for update;
  if actual is null or actual not in ('434217eb-9b7f-1cd9-a851-fbde7bced2bf'::uuid, 'eca89db7-aac5-35fa-f792-5bffbe8795e2'::uuid) then
    raise exception 'Publicación distinta de la revisión anterior prevista: %. No aplicar este lote.', actual;
  end if;
  if actual = '434217eb-9b7f-1cd9-a851-fbde7bced2bf'::uuid and not exists (select 1 from rwadar_catalogo.revisiones where id = '434217eb-9b7f-1cd9-a851-fbde7bced2bf'::uuid
    and contenido_sha256 = '434217eb9b7f1cd9a851fbde7bced2bf001c79ac17610ad1d2a24edb8a9c1b61' and estado = 'aprobada') then
    raise exception 'La revisión publicada no tiene la identidad prevista o no está aprobada. No aplicar este lote.';
  end if;
  select retirado into retirada from public.catalogo_publicacion where unica for update;
  if retirada is distinct from false then
    raise exception 'Catálogo retirado o control ausente: este lote no autoriza reactivarlo.';
  end if;
  if current_date < date '2026-11-20' then raise exception 'Revisión futura'; end if;
  if current_date > date '2026-11-27' then
    raise exception 'Lote caducado: sus fichas valían hasta el 27/11/2026. No aplicar este lote.';
  end if;
  if exists (select 1 from rwadar_catalogo.revisiones where id = 'eca89db7-aac5-35fa-f792-5bffbe8795e2'::uuid
    and (contenido_sha256 <> 'eca89db7aac535faf7925bffbe8795e2edf8096c80af6789c7ab59b960a5af43' or estado = 'retirada')) then
    raise exception 'La revisión destino existe con otra identidad o está retirada';
  end if;
end $guarda$;

do $aprobar$
declare v uuid := 'eca89db7-aac5-35fa-f792-5bffbe8795e2';
begin
  if (select count(*) from rwadar_catalogo.plataformas where revision_id = v) <> 25
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v) <> 22
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'principales') <> 8
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'secundario') <> 13
    or (select count(*) from rwadar_catalogo.ofertas where revision_id = v and coleccion = 'en_camino') <> 1 then
    raise exception 'Catálogo incompleto: se conserva el lote anterior';
  end if;
  update rwadar_catalogo.revisiones set estado = 'aprobada', aprobada_el = now(),
    aprobada_referencia = 'Entrega 2026-11-20: radar (69 fuentes) y 22 fichas comprobados el 20/11/2026 con fuentes primarias, expediente por oferta y revisión independiente; mismas 22 ofertas (8/13/1) y 25 plataformas. Puesta al día pedida por el responsable del proyecto el 20/11/2026; ciclo autorizado por su orden.'
    where id = v and estado = 'borrador';
  if not exists (select 1 from rwadar_catalogo.revision_publicable_v2 where id = v) then
    raise exception 'Entrega no publicable: se deshace la transacción completa';
  end if;
  if (select revision_id from rwadar_catalogo.publicacion_v2 where unica) is distinct from v then
    raise exception 'La revisión nueva no quedó publicada: se deshace la transacción completa';
  end if;
end $aprobar$;
commit;
